    string UserMessage,
    string? ReferenceResponse,
    string? Context,
    string[]? ExpectedTraits,
    string[]? ExpectedToolCalls)
{
    public override string ToString() => Id;
}

internal static class GoldenLoader
{
    private static readonly JsonSerializerOptions s_options = new()
    {
        PropertyNamingPolicy = JsonNamingPolicy.SnakeCaseLower,
        PropertyNameCaseInsensitive = true,
    };

    public static List<GoldenItem> Load()
    {
        var path = Path.Combine(AppContext.BaseDirectory, "Quality", "golden.json");
        var doc = JsonDocument.Parse(File.ReadAllText(path));
        var scenarios = doc.RootElement.GetProperty("scenarios");
        return JsonSerializer.Deserialize<List<GoldenItem>>(scenarios.GetRawText(), s_options) ?? new();
    }
}

internal static class RubricLoader
{
    public static string SystemPrompt()
    {
        var path = Path.Combine(AppContext.BaseDirectory, "Quality", "rubric.md");
        return File.Exists(path)
            ? File.ReadAllText(path)
            : "You are a helpful assistant.";
    }
}

internal static class Thresholds
{
    private static readonly JsonSerializerOptions s_options = new()
    {
        PropertyNameCaseInsensitive = true,
    };

    public static void ApplyOrLog(EvaluationResult result, string scenarioId)
    {
        var path = Path.Combine(AppContext.BaseDirectory, "quality.thresholds.json");
        if (!File.Exists(path)) return;

        var doc = JsonDocument.Parse(File.ReadAllText(path));
        var root = doc.RootElement;
        var hardFail = root.TryGetProperty("hard_fail", out var hf) && hf.GetBoolean();

        if (!root.TryGetProperty("thresholds", out var thresholds)) return;

        foreach (var metric in result.Metrics)
        {
            if (thresholds.TryGetProperty(metric.Key, out var threshold))
            {
                if (metric.Value is NumericMetric nm && nm.Value.HasValue)
                {
                    if (threshold.TryGetProperty("min_value", out var minVal))
                    {
                        if ((decimal)nm.Value.Value < minVal.GetDecimal())
                        {
                            var msg = $"[{scenarioId}] {metric.Key}={nm.Value.Value} below min {minVal}";
                            if (hardFail) Assert.Fail(msg);
                            else Console.WriteLine($"WARN: {msg}");
                        }
                    }
                    if (threshold.TryGetProperty("max_value", out var maxVal))
                    {
                        if ((decimal)nm.Value.Value > maxVal.GetDecimal())
                        {
                            var msg = $"[{scenarioId}] {metric.Key}={nm.Value.Value} above max {maxVal}";
                            if (hardFail) Assert.Fail(msg);
                            else Console.WriteLine($"WARN: {msg}");
                        }
                    }
                }
            }
        }
    }
}

