namespace MyApp.Evals.Tests;

internal static class ReportingConfig
{

// Mirror the app's registration. The Aspire hosting extension
// (AddAzureChatCompletionsClient) is not available in test projects.
// Instead, resolve from a connection string directly using MEAI.
var connStr = builder.Configuration.GetConnectionString("chat");
if (string.IsNullOrEmpty(connStr))
    throw new InvalidOperationException(
        "ConnectionStrings:chat not found. Set it via user-secrets or env var.");

builder.Services.AddSingleton<IChatClient>(_ =>
{
    // Parse the connection string: Endpoint=...;Key=...;DeploymentId=...
    var parts = connStr.Split(';')
        .Select(p => p.Split('=', 2))
        .Where(p => p.Length == 2)
        .ToDictionary(p => p[0].Trim(), p => p[1].Trim(), StringComparer.OrdinalIgnoreCase);

    parts.TryGetValue("Endpoint", out var endpoint);
    parts.TryGetValue("Key", out var key);
    parts.TryGetValue("DeploymentId", out var deploymentId);

    if (string.IsNullOrEmpty(endpoint))
        throw new InvalidOperationException("Connection string missing Endpoint.");

    var credential = !string.IsNullOrEmpty(key)
        ? (object)new System.ClientModel.ApiKeyCredential(key)
        : (object)new Azure.Identity.DefaultAzureCredential();

    var client = credential is System.ClientModel.ApiKeyCredential apiKey
        ? new Azure.AI.Inference.ChatCompletionsClient(new Uri(endpoint), apiKey)
        : new Azure.AI.Inference.ChatCompletionsClient(
            new Uri(endpoint), (Azure.Core.TokenCredential)(Azure.Identity.DefaultAzureCredential)credential);

    return client.AsChatClient(deploymentId ?? "chat");
});

var host = builder.Build();

